   }
+
+  /**
+   * Update the permission level of a share.
+   * Only the sharer (owner) can upgrade or downgrade permission.
+   * Upgrading to 'write' requires an ECIES-wrapped IPNS private key.
+   * Downgrading to 'read' clears the IPNS key.
+   */
+  async updatePermission(
+    shareId: string,
+    sharerId: string,
+    permission: 'read' | 'write',
+    encryptedIpnsKey?: string
+  ): Promise<void> {
+    const share = await this.shareRepo.findOne({ where: { id: shareId } });
+
+    if (!share) {
+      throw new NotFoundException('Share not found');
+    }
+
+    if (share.sharerId !== sharerId) {
+      throw new ForbiddenException('Only the sharer can change permission');
+    }
+
+    if (share.revokedAt) {
+      throw new ConflictException('Cannot change permission on a revoked share');
+    }
+
+    if (permission === 'write') {
+      if (!encryptedIpnsKey) {
+        throw new BadRequestException('encryptedIpnsKey required for write permission');
+      }
+      share.permission = 'write';
+      share.encryptedIpnsKey = Buffer.from(encryptedIpnsKey, 'hex');
+      await this.shareRepo.save(share);
+    } else {
+      // Downgrade atomically: update share + delete file-ipns keys in one transaction
+      await this.shareRepo.manager.transaction(async (txManager) => {
+        share.permission = 'read';
+        share.encryptedIpnsKey = null;
+        await txManager.save(share);
+        await txManager.delete(ShareKey, { shareId, keyType: 'file-ipns' });
+      });","path":"apps/api/src/shares/shares.service.ts","commit_id":"346505aca764c34c75bf61885c8f0aa3b8adc245","original_commit_id":"f407474ef644809666d8a49ac1bbbbc03d6d842a","user":{"login":"FSM1","id":12774278,"node_id":"MDQ6VXNlcjEyNzc0Mjc4","avatar_url":"https://avatars.githubusercontent.com/u/12774278?v=4","gravatar_id":"","url":"https://api.github.com/users/FSM1","html_url":"https://github.com/FSM1","followers_url":"https://api.github.com/users/FSM1/followers","following_url":"https://api.github.com/users/FSM1/following{/other_user}","gists_url":"https://api.github.com/users/FSM1/gists{/gist_id}","starred_url":"https://api.github.com/users/FSM1/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/FSM1/subscriptions","organizations_url":"https://api.github.com/users/FSM1/orgs","repos_url":"https://api.github.com/users/FSM1/repos","events_url":"https://api.github.com/users/FSM1/events{/privacy}","received_events_url":"https://api.github.com/users/FSM1/received_events","type":"User","user_view_type":"public","site_admin":false},"body":"Fixed in e1be280. The downgrade transaction now deletes both `file-ipns` and `folder-ipns` share keys using `In(['file-ipns', 'folder-ipns'])`, ensuring all write-enabling signing keys are removed when permission is downgraded to read.","created_at":"2026-03-27T01:18:59Z","updated_at":"2026-03-27T01:18:59Z","html_url":"https://github.com/FSM1/cipher-box/pull/372#discussion_r2998493936","pull_request_url":"https://api.github.com/repos/FSM1/cipher-box/pulls/372","_links":{"self":{"href":"https://api.github.com/repos/FSM1/cipher-box/pulls/comments/2998493936"},"html":{"href":"https://github.com/FSM1/cipher-box/pull/372#discussion_r2998493936"},"pull_request":{"href":"https://api.github.com/repos/FSM1/cipher-box/pulls/372"}},"reactions":{"url":"https://api.github.com/repos/FSM1/cipher-box/pulls/comments/2998493936/reactions","total_count":0,"+1":0,"-1":0,"laugh":0,"hooray":0,"confused":0,"heart":0,"rocket":0,"ey